import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"
import { Aurora, initAurora, VAR_SIZE, type AuroraSizeOverrides } from "@/lib/aurora"
import "./aurora-glow.css"

/* ─────────────────────────── 光晕 hook ───────────────────────────
   原 DOM 用 jsname 定位节点；光晕引擎角度逐帧变化，刻意不走 React 渲染，
   全部通过 ref + setProperty + rAF 驱动（与原站一致）。 */

interface GlowNodes {
  glowRef: React.RefObject<HTMLDivElement | null>
  varLayerRef: React.RefObject<HTMLDivElement | null>
  innerBlurRef: React.RefObject<HTMLDivElement | null>
}

function useAuroraGlow({ glowRef, varLayerRef, innerBlurRef }: GlowNodes) {
  const rootRef = React.useRef<HTMLButtonElement>(null)
  const auroraRef = React.useRef<Aurora | null>(null)

  React.useEffect(() => {
    const container = glowRef.current
    const varLayer = varLayerRef.current
    const blurLayer = innerBlurRef.current
    if (!container || !varLayer || !blurLayer) return

    /* 光晕圆角跟随按钮实际圆角（sizeVariant 写的 --aurora-button-radius） */
    const radius = getComputedStyle(container).getPropertyValue("--aurora-button-radius").trim()
    const sizeOverrides: AuroraSizeOverrides | undefined = radius
      ? { [VAR_SIZE.radius]: radius }
      : undefined

    const instance = initAurora({ container, varLayer, blurLayer, buttonContext: true }, sizeOverrides)
    if (!instance) return // 初始化失败时已把原因写进 data-aurora-error

    auroraRef.current = instance.aurora
    return () => {
      instance.dispose()
      delete container.dataset.auroraReady
      delete container.dataset.auroraError
      auroraRef.current = null
    }
  }, [glowRef, varLayerRef, innerBlurRef])

  /* hover/focus 进入：开始跟随（4/1.5 即原站 --aurora-scale-x / --aurora-scale-y） */
  const startFollow = React.useCallback(() => {
    const root = rootRef.current
    if (root) auroraRef.current?.startFollow(root, 4, 1.5)
  }, [])

  /* hover/focus 离开：淡出并停止 */
  const stopFollow = React.useCallback(() => {
    auroraRef.current?.stopFollow()
  }, [])

  return { rootRef, startFollow, stopFollow }
}

/* ─────────────────────────── variants ─────────────────────────── */

const auroraButtonVariants = cva(
  // 基础：原 .plR5qb 的定位与字形（底色/圆角由 glow 容器层渲染，见 aurora-glow.css）
  [
    "relative inline-flex shrink-0 cursor-pointer select-none items-center justify-center",
    "border-0 bg-transparent p-0 text-[14px] leading-none font-normal outline-none",
    "[border-radius:var(--aurora-button-radius,100px)]",
    "[margin-inline-start:var(--aurora-button-margin-inline-start,0px)]",
    "focus-visible:[&_.aurora-surface]:outline focus-visible:[&_.aurora-surface]:outline-2",
    "focus-visible:[&_.aurora-surface]:outline-offset-2 focus-visible:[&_.aurora-surface]:outline-[#1a73e8]",
  ],
  {
    variants: {
      /** 视觉主题 */
      variant: {
        /** 默认：浅灰底（原 .bvUkz 默认态） */
        default: "[--aurora-surface:#f0f4f9] [--aurora-text:#1f1f1f]",
        /** 强调态：蓝色调（原 .VzUPFe） */
        highlighted: "[--aurora-surface:#d3e3fd] [--aurora-text:#0b57d0]",
        /** 无底色虚化（原 .PHjFye）：hover 不模糊 */
        plain: "[--aurora-surface:#f0f4f9] [--aurora-text:#1f1f1f] hover:[&_.aurora-surface]:blur-none",
        /** 透明底：只留光晕 */
        ghost: "[--aurora-surface:transparent] [--aurora-text:inherit]",
      },
      /** 尺寸（高度 + 水平内边距） */
      size: {
        /** 原站默认 36px */
        default: "[--aurora-button-height:36px] [--aurora-button-padding-x:8px]",
        /** 原站收起态 24px */
        sm: "[--aurora-button-height:24px] [--aurora-button-padding-x:6px]",
        /** 大号 */
        lg: "[--aurora-button-height:48px] [--aurora-button-padding-x:16px]",
        /** 图标按钮：正方形 */
        icon: "[--aurora-button-height:36px] [--aurora-button-padding-x:0px] w-9",
      },
      /** 圆角（光晕自动跟随） */
      radius: {
        pill: "[--aurora-button-radius:100px]",
        rounded: "[--aurora-button-radius:8px]",
        square: "[--aurora-button-radius:0px]",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
      radius: "pill",
    },
  },
)

/* ─────────────────────────── 组件 ─────────────────────────── */

export interface AuroraButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof auroraButtonVariants> {
  /** 是否禁用 hover 底色虚化（原 .PHjFye）；variant="plain" 时已隐含 */
  noBlur?: boolean
}

/** 图标占位宽度：原站图标 20×20，文字 margin-inline-start 20px 预留图标位 */
const AuroraButton = React.forwardRef<HTMLButtonElement, AuroraButtonProps>(function AuroraButton(
  { className, variant, size, radius, noBlur, children, onMouseEnter, onMouseLeave, onFocus, onBlur, ...props },
  ref,
) {
  const glowRef = React.useRef<HTMLDivElement>(null)
  const varLayerRef = React.useRef<HTMLDivElement>(null)
  const innerBlurRef = React.useRef<HTMLDivElement>(null)
  const { rootRef, startFollow, stopFollow } = useAuroraGlow({ glowRef, varLayerRef, innerBlurRef })

  /* 合并外部 ref（React 19 之前 forwardRef 只能给一个，手动串接） */
  const setRefs = React.useCallback(
    (node: HTMLButtonElement | null) => {
      rootRef.current = node
      if (typeof ref === "function") ref(node)
      else if (ref) (ref as React.MutableRefObject<HTMLButtonElement | null>).current = node
    },
    [ref],
  )

  /* hover/focus 跟随光晕，同时把调用方自己的同名事件接在后面 */
  const handleEnter = (event: React.MouseEvent<HTMLButtonElement>) => {
    startFollow()
    onMouseEnter?.(event)
  }
  const handleLeave = (event: React.MouseEvent<HTMLButtonElement>) => {
    stopFollow()
    onMouseLeave?.(event)
  }
  const handleFocus = (event: React.FocusEvent<HTMLButtonElement>) => {
    startFollow()
    onFocus?.(event)
  }
  const handleBlur = (event: React.FocusEvent<HTMLButtonElement>) => {
    stopFollow()
    onBlur?.(event)
  }

  const hideBlur = noBlur || variant === "plain"

  return (
    <button
      ref={setRefs}
      type="button"
      className={cn(        "aurora-button",        auroraButtonVariants({ variant, size, radius }),        hideBlur && "aurora-plain",        className,      )}
      style={{ height: "var(--aurora-button-height, 36px)", padding: "0 var(--aurora-button-padding-x, 8px)" }}
      onMouseEnter={handleEnter}
      onMouseLeave={handleLeave}
      onFocus={handleFocus}
      onBlur={handleBlur}
      {...props}
    >
      {/* 光晕层结构逐层对应原 DOM：CcxW7b > BznTFe > fZhNMe > WkMYIb > (eruMcc > Tdahud > tgPjse) × 2 */}
      <span className="pointer-events-none absolute inset-0 opacity-60" aria-hidden="true">
        <span ref={glowRef} className="aurora-glow absolute inset-0 overflow-visible">
          <span ref={varLayerRef} className="aurora-var-layer absolute inset-0">
            {/* 对应原 .WkMYIb：border-radius 必须逐层继承，否则模糊层矩形裁剪漏出色块 */}
            <span className="absolute inset-0 [border-radius:inherit]">
              <span ref={innerBlurRef} className="aurora-blur">
                <span className="aurora-mask">
                  <span className="aurora-disc" />
                </span>
              </span>
              <span className="aurora-blur aurora-blur-inner">
                <span className="aurora-mask">
                  <span className="aurora-disc" />
                </span>
              </span>
            </span>
          </span>
        </span>
      </span>

      {/* 按钮底色层（原 .bvUkz）：颜色由 variant 注入的 CSS 变量决定 */}
      <span
        className="aurora-surface pointer-events-none absolute inset-[1px] [clip-path:inset(0_round_var(--aurora-button-radius,100px))]"
        style={{
          borderRadius: "var(--aurora-button-radius, 100px)",
          background: "var(--aurora-surface, #f0f4f9)",
        }}
      />

      {/* 内容区 */}
      <span className="relative z-[1] flex items-center justify-center gap-1.5 text-[color:var(--aurora-text,#1f1f1f)]">
        {children}
      </span>
    </button>
  )
})

export { AuroraButton, auroraButtonVariants }

/* ============================================================================
   aurora-glow.css —— Aurora 光晕层精确样式
   ---------------------------------------------------------------------------
   数值逐字节取自原站 CSSOM（sheet-33/34-BUTTON），仅类名与 CSS 变量名语义化：
     类名对照
       aurora-glow       ← 原 .BznTFe（光晕容器，5 个尺寸变量写在这里）
       aurora-var-layer  ← 原 .fZhNMe（变量层，两个角度变量写在这里）
       aurora-blur       ← 原 .eruMcc（模糊层）
       aurora-blur-inner ← 原 .eOuHwe（内层模糊 blur 1px）
       aurora-mask       ← 原 .Tdahud（角度遮罩层）
       aurora-disc       ← 原 .tgPjse（彩虹圆盘）
     变量对照（原站运行时哈希名 → 本项目语义名，即原站 _.Sg 的注册名）
       --q9niGe  →  --aurora-mask-angle       --cqcjz   →  --aurora-gradient-angle
       --BgHDjb  →  --aurora-radius           --bFlrOb  →  --aurora-blur
       --HM63Tc  →  --aurora-inset            --sjdAce  →  --aurora-scale-x
       --mWus4b  →  --aurora-scale-y
   @property 声明在本文件顶部（角度可插值的前提），
   使本组件不依赖宿主的全局 CSS。
   ============================================================================ */

/* ── 角度变量注册（角度可插值的前提，原站由 CSS.registerProperty 运行时注册）── */
@property --aurora-mask-angle {
  syntax: "<angle>";
  inherits: true;
  initial-value: 0deg;
}
@property --aurora-gradient-angle {
  syntax: "<angle>";
  inherits: true;
  initial-value: 0deg;
}

/* ── 光晕容器（原 .BznTFe）──────────────────────────────────────────────
   CSS 回退值取自原文；运行时由 aurora.ts 写入实际值（100px/4px/-1px/4/1.5，
   radius 会按宿主按钮的 --aurora-button-radius 自动跟随） */
.aurora-glow {
  --aurora-radius: 24px;
  --aurora-blur: 5px;
  --aurora-scale-x: 7;
  --aurora-scale-y: 1.5;
  --aurora-inset: 0;
  position: absolute;
  inset: 0;
  border-radius: var(--aurora-radius);
  pointer-events: none;
  z-index: 0;
  overflow: visible;
  will-change: height;
  transition: height 0.15s;
}

/* ── 变量层（原 .fZhNMe）：JS 把两个角度变量写在这里 ─────────────────── */
.aurora-var-layer {
  --aurora-gradient-angle: 0deg;
  --aurora-mask-angle: 0deg;
  position: absolute;
  inset: 0;
  border-radius: inherit;
  opacity: 0;
  will-change: --aurora-mask-angle, --aurora-gradient-angle, opacity;
}

/* ── 模糊层（原 .eruMcc）────────────────────────────────────────────── */
.aurora-blur {
  inset: var(--aurora-inset, 0);
  position: absolute;
  border-radius: inherit;
  overflow: hidden;
  backface-visibility: hidden;
  transform: translateZ(0);
  filter: blur(var(--aurora-blur, 5px));
}
.aurora-blur-inner {
  filter: blur(1px);
}

/* ── 角度遮罩层（原 .Tdahud）────────────────────────────────────────── */
.aurora-mask {
  inset: 0;
  position: absolute;
  border-radius: inherit;
  -webkit-mask-image:
    conic-gradient(from var(--aurora-mask-angle), transparent 0, transparent 50%, black 68%, black 75%, transparent 89%),
    conic-gradient(from var(--aurora-mask-angle), black 30%, transparent 50%, black 70%);
  mask-image:
    conic-gradient(from var(--aurora-mask-angle), transparent 0, transparent 50%, black 68%, black 75%, transparent 89%),
    conic-gradient(from var(--aurora-mask-angle), black 30%, transparent 50%, black 70%);
  scale: var(--aurora-scale-x, 7) var(--aurora-scale-y, 1.5);
  -webkit-mask-composite: source-in, xor;
  mask-composite: intersect;
}
.aurora-blur-inner .aurora-mask {
  -webkit-mask-image:
    conic-gradient(from var(--aurora-mask-angle), transparent 0, transparent 62%, black 82%, transparent 89%),
    conic-gradient(from var(--aurora-mask-angle), black 30%, transparent 50%, black 70%);
  mask-image:
    conic-gradient(from var(--aurora-mask-angle), transparent 0, transparent 62%, black 82%, transparent 89%),
    conic-gradient(from var(--aurora-mask-angle), black 30%, transparent 50%, black 70%);
}

/* ── 彩虹圆盘（原 .tgPjse）：15 段色标，逐字节一致 ──────────────────── */
.aurora-disc {
  inset: 0;
  position: absolute;
  border-radius: 50%;
  background: conic-gradient(
    #3186ff 34%, #9378ff 37%, #f96bd6 39%, #fc413d 41%, #fc413d 48%,
    #ff6b2b 50%, #fec700 52%, #ffdb0f 56%, #88de42 58%, #0ebc5f 61%,
    #0ebc5f 65%, #2eaab2 70%, #00a9bb 72%, #3186ff 73%, #3186ff 83%,
    #3186ff 100%
  );
  aspect-ratio: 1 / 1;
  translate: 0 -50%;
  inset-block-start: 50%;
  rotate: var(--aurora-gradient-angle);
  backface-visibility: hidden;
  transform: translateZ(0);
}

/* hover 底色虚化（原 .plR5qb:not(.PHjFye):hover .bvUkz）——
   默认态启用；variant=plain / noBlur 时由组件以 blur-none 覆盖 */
.aurora-surface {
  transition: filter 0.15s;
}
.aurora-button:not(.aurora-plain):hover .aurora-surface {
  filter: blur(2px);
}

/* 尊重系统「减弱动态效果」 */
@media (prefers-reduced-motion: reduce) {
  .aurora-glow {
    transition: none;
  }
  .aurora-surface {
    transition: none;
  }
  .aurora-button:not(.aurora-plain):hover .aurora-surface {
    filter: none;
  }
}

/* ============================================================================
   aurora.ts —— 原始算法的 TS 搬运
   ---------------------------------------------------------------------------
   来源：./source/ORIGINAL-js.js（从 xjs bundle scriptId 737 逐字节切出）
   算法逐字节保真；标识符已按语义重命名，下方对照表仅用于回溯 bundle 原文。

   函数 / 类 对照（bundle 混淆名 → 本项目语义名）：
     zQE    →  computeTargetAngle     由鼠标位置求目标方位角
     AQE    →  lerpShortest           沿最短路径的角度插值
     BQE    →  runFrame               rAF 主循环
     _.CQE  →  class Aurora           Aurora 动画器
     EQE    →  createAurora           组件初始化
     _.u6c  →  prefersReducedMotion   系统「减弱动态效果」检测

   Aurora 实例字段对照：
     Aa  →  glowContainer      ka  →  variableLayer     Wa  →  blurLayer
     yb  →  isButtonContext    Ia  →  runningAnimations nb  →  isPlaying
     Ma  →  gradientAngle      wa  →  maskAngle         mJa →  targetAngle
     Qa  →  isFollowing        Pa  →  fadeAnimation     oa  →  angularVelocity
     Ca  →  rafId              bzb →  hoverElement      nQ  →  pointerScaleX
     oQ  →  pointerScaleY      Ka  →  buttonRect        Ya  →  handleMouseMove

   Aurora 方法对照：
     Sa    →  startFollow（鼠标进入，开始跟随）
     Ha    →  stopFollow （鼠标离开，淡出并停止跟随）

   CSS 变量对照（原站运行时哈希名 → 本项目语义名，即原站 _.Sg 的注册名）：
     --q9niGe  →  --aurora-mask-angle       --cqcjz   →  --aurora-gradient-angle
     --BgHDjb  →  --aurora-radius           --bFlrOb  →  --aurora-blur
     --HM63Tc  →  --aurora-inset            --sjdAce  →  --aurora-scale-x
     --mWus4b  →  --aurora-scale-y
   ============================================================================ */

/* ──────────────────────────── CSS 变量名 ──────────────────────────── */

/** 原 _.Sg("aurora-mask-angle") 运行时映射到的实际变量名 */
export const VAR_MASK_ANGLE = "--aurora-mask-angle";
/** 原 _.Sg("aurora-gradient-angle") 运行时映射到的实际变量名 */
export const VAR_GRADIENT_ANGLE = "--aurora-gradient-angle";

/** 原 _.Sg("aurora-radius" | "aurora-blur" | "aurora-inset" | "aurora-scale-x" | "aurora-scale-y") */
export const VAR_SIZE = {
  radius: "--aurora-radius",
  blur: "--aurora-blur",
  inset: "--aurora-inset",
  scaleX: "--aurora-scale-x",
  scaleY: "--aurora-scale-y",
} as const;

/** EQE 写入的 5 个尺寸值（原文逐字节） */
export const SIZE_VALUES = {
  [VAR_SIZE.radius]: "100px",
  [VAR_SIZE.blur]: "4px",
  [VAR_SIZE.inset]: "-1px",
  [VAR_SIZE.scaleX]: "4",
  [VAR_SIZE.scaleY]: "1.5",
} as const;

/** 写入时的两个偏移常量（原文 `a.wa + -167` / `a.Ma + -142`） */
export const MASK_OFFSET_DEG = -167;
export const GRADIENT_OFFSET_DEG = -142;

/* ──────────────────────── 弹簧-阻尼 / 低通参数 ──────────────────────── */

/** 角速度每帧增量系数（原文 `v += Δ*0.05`） */
const SPRING_ACCEL_FACTOR = 0.05;
/** 低通增益的角差饱和值：角差 ≥ 90° 时增益取满（原文 `min(|Δ|/90, 1)`） */
const GAIN_NORMALIZE_DEG = 90;
/** 低通增益曲线的三次方（原文 `pow(..., 3)`） */
const GAIN_EXPONENT = 3;
/** 显隐淡入淡出时长，对应原文两处 350ms opacity 动画 */
const FADE_DURATION_MS = 350;
/** 入场动画时长：animate(!0, 1E3) 与移除入场 class 的 setTimeout 共用 */
const ENTER_DURATION_MS = 1000;

/** 按钮矩形（原文直接读 DOMRect 的 top/left/width/height） */
export interface ButtonRect {
  top: number;
  left: number;
  width: number;
  height: number;
}

/* ────────────────────────────────────────────────────────────────────────────
   原 zQE：由鼠标位置求目标方位角
     zQE=function(a,b,c,d,e=7,f=1.5){
       a.mJa=180/Math.PI*Math.atan2((c-(d.top+d.height/2))/f,(b-(d.left+d.width/2))/e)
     };
   b=clientX  c=clientY  d=rect  e=scaleX  f=scaleY
   除 e/f 即「先缩放到圆盘空间再求角」，与 CSS scale(--aurora-scale-x, --aurora-scale-y) 同源。
   ──────────────────────────────────────────────────────────────────────────── */
export function computeTargetAngle(
  clientX: number,
  clientY: number,
  rect: ButtonRect,
  scaleX = 7,
  scaleY = 1.5,
): number {
  return (180 / Math.PI) * Math.atan2(
    (clientY - (rect.top + rect.height / 2)) / scaleY,
    (clientX - (rect.left + rect.width / 2)) / scaleX,
  );
}

/* ────────────────────────────────────────────────────────────────────────────
   原 AQE：沿最短路径的角度插值
     AQE=function(a,b,c){b=(b-a)%360;return a+(2*b%360-b)*c};
   `2*delta%360-delta` 把任意角差折成 (-180, 180]，避免绕远路。
   ──────────────────────────────────────────────────────────────────────────── */
export function lerpShortest(from: number, to: number, factor: number): number {
  const delta = (to - from) % 360;
  return from + ((2 * delta) % 360 - delta) * factor;
}

/** 最短有向角差，等价于上面的 `(2*delta%360 - delta)` */
function shortestDelta(from: number, to: number): number {
  const delta = (to - from) % 360;
  return (2 * delta) % 360 - delta;
}

/** 原 _.u6c() */
export function prefersReducedMotion(): boolean {
  if (typeof window === "undefined" || !window.matchMedia) return false;
  return (
    window.matchMedia("(prefers-reduced-motion)").matches ||
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

/** Aurora 构造参数（对应 _.CQE 构造签名 `(Aa, ka, Wa, Aq, yb)`） */
export interface AuroraTargets {
  /** Aa：光晕容器（aurora-glow）——入场时同步高度，本例仅用于非空判断 */
  container: HTMLElement;
  /** ka：变量层（aurora-var-layer）——两个角度写在它身上 */
  varLayer: HTMLElement;
  /** Wa：内层模糊层（aurora-blur-inner）——入场时做 blur 动画 */
  blurLayer: HTMLElement;
  /** yb：是否按钮语境（决定入场 blur 曲线用 5/3/5 还是 20/5/7） */
  buttonContext?: boolean;
}

/** 一次低通滤波后的两个输出角 */
export interface AuroraAngles {
  maskAngle: number;
  gradientAngle: number;
}

/* ────────────────────────────────────────────────────────────────────────────
   原 _.CQE —— Aurora 动画器
   字段与方法的原名见文件头对照表；实现与原文一一对应。
   ──────────────────────────────────────────────────────────────────────────── */
export class Aurora {
  /** Aa：光晕容器 */
  private glowContainer: HTMLElement;
  /** ka：变量层 */
  private variableLayer: HTMLElement;
  /** Wa：内层模糊层 */
  private blurLayer: HTMLElement;
  /** yb：是否按钮语境 */
  private isButtonContext: boolean;

  /** Ia：进行中的 Web Animations 列表 */
  private runningAnimations: Animation[] = [];
  /** nb：当前 animate 状态（true=播放中），用于幂等判断 */
  private isPlaying = false;
  /** Ma：渐变角（慢通道输出）；wa：遮罩角（快通道输出）；mJa：目标角 */
  private gradientAngle = 0;
  private maskAngle = 0;
  private targetAngle = 0;
  /** Qa：是否正在跟随鼠标 */
  private isFollowing = false;
  /** Pa：显隐动画（startFollow/stopFollow 里的 350ms opacity 动画） */
  private fadeAnimation: Animation | null = null;
  /** oa：角速度；Ca：rAF 句柄 */
  private angularVelocity = 0;
  private rafId = 0;
  /** 摩擦系数（原文写死 .75） */
  private friction = 0.75;
  /** bzb：当前挂 mousemove 的元素 */
  private hoverElement: HTMLElement | null = null;
  /** nQ/oQ：归一化除数（= --aurora-scale-x / --aurora-scale-y） */
  private pointerScaleX = 7;
  private pointerScaleY = 1.5;
  /** Ka：缓存的按钮 rect（避免每帧读取） */
  private buttonRect: ButtonRect | null = null;
  /** Ya：mousemove 处理器 */
  private handleMouseMove = (event: MouseEvent) => {
    if (this.buttonRect) this.setTarget(event.clientX, event.clientY);
  };

  constructor(targets: AuroraTargets) {
    this.glowContainer = targets.container;
    this.variableLayer = targets.varLayer;
    this.blurLayer = targets.blurLayer;
    this.isButtonContext = targets.buttonContext ?? false;
  }

  /* 原 handleMouseMove 内联的 zQE 调用，单独抽出以便可读 */
  private setTarget(clientX: number, clientY: number): void {
    if (!this.buttonRect) return;
    this.targetAngle = computeTargetAngle(
      clientX,
      clientY,
      this.buttonRect,
      this.pointerScaleX,
      this.pointerScaleY,
    );
  }

  /* ── 原 animate(a, b=650)：入场动画 ─────────────────────────────────────
     isVisible=true 播放 / false 取消；durationMs 默认 650ms，按钮语境传 1000ms。
     三条动画并行：容器 opacity、内层 blur、两个角度从固定起点扫到固定终点。 */
  animate(isVisible: boolean, durationMs = 650): void {
    if (!this.glowContainer || prefersReducedMotion()) return;
    const isFreshStart = !this.isPlaying && isVisible;
    this.isPlaying = isVisible;
    if (!isFreshStart) {
      if (!isVisible) this.cancel();
      return;
    }

    this.cancel();
    /* 原文在此处 CSS.registerProperty 两个角度变量；本移植版用 @property（见 index.css 顶部） */

    if (!(this.variableLayer && this.blurLayer && isVisible)) return;

    // ① 容器透明度：0 → 1 → 1 → 0（两端各带缓动）
    const opacityAnimation = this.variableLayer.animate(
      [
        { opacity: 0, easing: "cubic-bezier(0, 0, 0, 1)", offset: 0 },
        { opacity: 1, offset: 0.25 },
        { opacity: 1, easing: "cubic-bezier(0.30, 0.00, 0.80, 0.15)", offset: 0.5 },
        { opacity: 0, offset: 1 },
      ],
      { duration: durationMs, fill: "both" },
    );

    // ② 内层 blur 呼吸。按钮语境用 5/3/5，非按钮语境用 20/5/7
    const blurAnimation = this.blurLayer.animate(
      this.isButtonContext
        ? [
            { filter: "blur(1px)" },
            { filter: "blur(5px)", offset: 0.15 },
            { filter: "blur(3px)", offset: 0.25 },
            { filter: "blur(5px)", offset: 0.45 },
            { filter: "blur(1px)" },
          ]
        : [
            { filter: "blur(1px)" },
            { filter: "blur(20px)", offset: 0.15 },
            { filter: "blur(5px)", offset: 0.25 },
            { filter: "blur(7px)", offset: 0.45 },
            { filter: "blur(1px)" },
          ],
      { duration: durationMs, fill: "both", easing: "linear" },
    );

    // ③ 两个角度从固定起点扫到固定终点（与鼠标位置无关）
    const angleAnimation = this.variableLayer.animate(
      [
        { [VAR_GRADIENT_ANGLE]: "170deg", [VAR_MASK_ANGLE]: "-90deg", easing: "cubic-bezier(0, 0, 0, 1)" },
        { [VAR_GRADIENT_ANGLE]: "225deg", [VAR_MASK_ANGLE]: "200deg" },
      ],
      { duration: durationMs, fill: "both" },
    );

    this.runningAnimations.push(opacityAnimation, blurAnimation, angleAnimation);
    for (const animation of this.runningAnimations) {
      animation.playbackRate = 1;
      animation.play();
    }
  }

  cancel(): void {
    for (const animation of this.runningAnimations) animation.cancel();
    this.runningAnimations.length = 0;
  }

  /* ── 原 Sa(a, b=7, c=1.5)：鼠标进入，开始跟随 ──────────────────────────
     注意：角度不归零，只归零速度；所以再次进入会从上次角度平滑接续。 */
  startFollow(element: HTMLElement, scaleX = 7, scaleY = 1.5): void {
    if (!this.variableLayer) return;
    this.hoverElement = element;
    this.pointerScaleX = scaleX;
    this.pointerScaleY = scaleY;
    this.buttonRect = element.getBoundingClientRect();
    this.isFollowing = true;
    this.angularVelocity = 0;
    this.cancel();
    this.fadeAnimation?.cancel();
    this.fadeAnimation = this.variableLayer.animate([{ opacity: 1 }], {
      duration: FADE_DURATION_MS,
      fill: "forwards",
    });
    element.addEventListener("mousemove", this.handleMouseMove);
    if (!this.rafId) runFrame(this);
  }

  /* ── 原 Ha()：鼠标离开，淡出并停止跟随 ──────────────────────────────────
     isFollowing 置 false 后，rAF 会在下一帧自行结束（不是立刻 cancelAnimationFrame）。 */
  stopFollow(): void {
    if (!this.variableLayer) return;
    this.isFollowing = false;
    this.angularVelocity = 0;
    this.fadeAnimation?.cancel();
    this.fadeAnimation = this.variableLayer.animate(
      [{ opacity: 1 }, { opacity: 0 }],
      { duration: FADE_DURATION_MS, fill: "forwards" },
    );
    if (this.hoverElement) {
      this.hoverElement.removeEventListener("mousemove", this.handleMouseMove);
      this.hoverElement = null;
    }
    this.buttonRect = null;
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = 0;
    }
  }

  /** 供 rAF 循环读写（对应原文对实例字段的直接访问） */
  computeAngles(): AuroraAngles | null {
    if (!this.isFollowing) return null;

    /* 原 BQE 前半段：弹簧-阻尼积分器
         v += Δ*0.05;  v *= 0.75;  a += v   （Δ 为最短有向角差） */
    this.angularVelocity += shortestDelta(this.maskAngle, this.targetAngle) * SPRING_ACCEL_FACTOR;
    this.angularVelocity *= this.friction;
    this.maskAngle += this.angularVelocity;

    /* 原 BQE 后半段：三次门控低通
         Ma = AQE(Ma, wa, pow(min(|Δ|/90, 1), 3))
       角差大时增益趋于 1（瞬时跟上），角差小时增益趋近 0（冻结色相）。 */
    const delta = (this.maskAngle - this.gradientAngle) % 360;
    const gain = Math.pow(
      Math.min(Math.abs((2 * delta) % 360 - delta) / GAIN_NORMALIZE_DEG, 1),
      GAIN_EXPONENT,
    );
    this.gradientAngle = lerpShortest(this.gradientAngle, this.maskAngle, gain);

    return { maskAngle: this.maskAngle, gradientAngle: this.gradientAngle };
  }

  scheduleFrame(id: number): void {
    this.rafId = id;
  }

  /** 写变量（对应原 BQE 里两次 setProperty，偏移常量原样） */
  private writeAngles(maskAngle: number, gradientAngle: number): void {
    this.variableLayer.style.setProperty(
      VAR_MASK_ANGLE,
      `${maskAngle + MASK_OFFSET_DEG}deg`,
    );
    this.variableLayer.style.setProperty(
      VAR_GRADIENT_ANGLE,
      `${gradientAngle + GRADIENT_OFFSET_DEG}deg`,
    );
  }

  /* 对外暴露一次的写入入口，避免 computeAngles 直接操作 DOM 破坏封装 */
  writeAnglesOnce(angles: AuroraAngles): void {
    this.writeAngles(angles.maskAngle, angles.gradientAngle);
  }
}

/* ────────────────────────────────────────────────────────────────────────────
   原 BQE —— rAF 主循环
     BQE=function(a){ if(a.Qa){ ...; a.ka&&(setProperty × 2); a.Ca=requestAnimationFrame(()=>BQE(a)) } };
   等价实现：读角度 → 写变量 → 排下一帧。
   ──────────────────────────────────────────────────────────────────────────── */
function runFrame(aurora: Aurora): void {
  const nextAngles = aurora.computeAngles();
  if (!nextAngles) return;
  aurora.writeAnglesOnce(nextAngles);
  aurora.scheduleFrame(requestAnimationFrame(() => runFrame(aurora)));
}

/* ────────────────────────────────────────────────────────────────────────────
   原 EQE —— 组件初始化
     EQE=function(a){
       a.oa=new _.CQE(IVmF1e, HQj0A, JoEfzc, void 0, !0);
       b.style.setProperty(--border-radius,"100px"); ... × 5
       a.oa?.animate(!0, 1E3);
       a.k0.classList.add("aurora-entering"); setTimeout(remove, 1E3);
       a.addOnDisposeCallback(()=>{ clearTimeout(c); a.oa?.Ha() })
     };
   注：原文入场加的 class 是未定义样式的哈希名 "HYcHq"，本项目按语义改名为
   "aurora-entering"（仓库内同样没有对应规则，行为与原文一致：仅加/删 class）。
   ──────────────────────────────────────────────────────────────────────────── */
export function createAurora(
  targets: AuroraTargets,
  sizeOverrides?: AuroraSizeOverrides,
): { aurora: Aurora; dispose: () => void } {
  const aurora = new Aurora(targets);

  // 5 个尺寸变量写在光晕容器上，供下层继承；sizeOverrides 可覆盖任意项
  const sizes: Record<string, string> = { ...SIZE_VALUES, ...sizeOverrides };
  for (const [variableName, value] of Object.entries(sizes)) {
    targets.container.style.setProperty(variableName, value);
  }

  aurora.animate(true, ENTER_DURATION_MS);

  const enterClassTimerId = window.setTimeout(() => {
    targets.container.classList.remove("aurora-entering");
  }, ENTER_DURATION_MS);

  return {
    aurora,
    dispose: () => {
      window.clearTimeout(enterClassTimerId);
      aurora.stopFollow();
      aurora.cancel();
    },
  };
}

/**
 * 尺寸变量覆盖：通用化后允许宿主改写光晕的 5 个尺寸
 * （key 为语义变量名，如 --aurora-radius；value 为 CSS 长度/数值）
 */
export type AuroraSizeOverrides = Partial<Record<(typeof VAR_SIZE)[keyof typeof VAR_SIZE], string>>;

export function initAurora(
  targets: AuroraTargets,
  sizeOverrides?: AuroraSizeOverrides,
): { aurora: Aurora; dispose: () => void } | null {
  try {
    const instance = createAurora(targets, sizeOverrides);
    targets.container.dataset.auroraReady = "1";
    delete targets.container.dataset.auroraError;
    return instance;
  } catch (error) {
    targets.container.dataset.auroraReady = "0";
    targets.container.dataset.auroraError =
      error instanceof Error ? `${error.name}: ${error.message}` : String(error);
    return null;
  }
}
